def calculate_revenue(rank: int) -> float:
    """Calculates realistic revenue in billions for a given Fortune 500 rank."""
    if rank == 1: return 648.1
    if rank == 2: return 574.8
    if rank == 3: return 383.3
    if rank == 4: return 371.6
    if rank == 5: return 364.5
    if rank == 6: return 357.8
    if rank == 7: return 344.6
    if rank == 8: return 307.4
    if rank == 9: return 276.7
    if rank == 10: return 269.8
    if rank == 11: return 242.3
    if rank == 12: return 239.4
    if rank == 13: return 211.9
    if rank == 14: return 205.0
    if rank == 15: return 200.9
    if rank == 16: return 195.3
    if rank == 17: return 176.2
    if rank == 18: return 171.9
    if rank == 19: return 171.8
    if rank == 20: return 171.3
    if rank >= 495: return 7.1

    t = (rank - 21) / (494 - 21)
    rev = 168.0 * math.exp(-3.15 * t)
    return round(max(7.1, rev), 1)

