TOP_20_COMPANIES = ALL_AUTHENTIC_COMPANIES[:20]
TAIL_COMPANIES = ALL_AUTHENTIC_COMPANIES[-6:]

def generate_fortune500_companies() -> List[Dict[str, Any]]:
    """Builds and returns all 500 authentic Fortune 500 enterprise records with contiguous ranks 1..500."""
    companies = []
    prev_rev = 1000000.0
    for entry in ALL_AUTHENTIC_COMPANIES:
        rank, name, slug, ind_id, sub_sector, b_model, arch = entry
        rev = calculate_revenue(rank)
        if rev > prev_rev:
            rev = prev_rev
        prev_rev = rev
        companies.append({
            "id": f"f500_{slug}",
            "slug": slug,
            "name": name,
            "rank": rank,
            "revenue_billions": rev,
            "macro_industry": INDUSTRY_MAP[ind_id],
            "industry_id": ind_id,
            "sub_sector": sub_sector,
            "business_model": b_model,
            "operating_archetype": arch,
            "functional_units_json": "[]",
            "metadata_json": "{}"
        })
    companies.sort(key=lambda x: x["rank"])
    return companies

FORTUNE_500_COMPANIES = generate_fortune500_companies()
